CREATE OR REPLACE FUNCTION public.icash_claim_discovery_estimate(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.estimates;peer icash_research_private.estimates;op text;generation timestamptz;t uuid:=gen_random_uuid();
begin
 if jsonb_typeof(p_query) is distinct from 'object' or octet_length(p_query::text)>16384
  or p_query->'estimate_cost' is distinct from 'true'::jsonb or p_query->>'contact_audience' is distinct from 'none'
  or p_query->>'anchor' is distinct from 'properties' then return jsonb_build_object('status','held');end if;
 if p_policy->>'version'='financial-prefilter-v1' and not icash_research_private.financial_query_valid(p_query,p_policy,p_plan,p_scope) then return jsonb_build_object('status','held');end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not public.icash_research_query_ready(p_account,p_scope,p_plan,p_policy) then return jsonb_build_object('status','held');end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 if p_policy->>'exclusionListId' is not null then
  select last_synced_at into generation from icash_research_private.exclusions where id=1 and list_id=p_policy->>'exclusionListId';
  if generation is null then return jsonb_build_object('status','held');end if;
 end if;
 insert into icash_research_private.estimates(operation_key,account_id,query,exclusion_synced_at)
 values(op,p_account,p_query,generation) on conflict do nothing;
 select * into e from icash_research_private.estimates where operation_key=op and account_id=p_account for update;
 if not found or e.lease_until>now() then return jsonb_build_object('status','held');end if;
 if e.query=p_query and e.exclusion_synced_at is not distinct from generation then
  if e.response is not null and e.saved_at>now()-interval '5 minutes' then return jsonb_build_object('status','cached','response',e.response);end if;
  if e.retry_at>now() then return jsonb_build_object('status','held');end if;
 end if;

 -- The existing operating-budget lock serializes these claims across accounts.
 -- A lease survives the transaction and coalesces the actual free network call.
 -- Hash is an index aid only: exact JSON and exclusion generation must match.
 select * into peer from icash_research_private.estimates other
 where other.operation_key<>op and md5(other.query::text)=md5(p_query::text)
  and other.query=p_query and other.exclusion_synced_at is not distinct from generation
  and (other.lease_until>now() or other.retry_at>now()
   or (other.response is not null and other.saved_at between now()-interval '5 minutes' and now()))
 order by (other.response is not null and other.saved_at between now()-interval '5 minutes' and now()) desc nulls last,
  other.saved_at desc nulls last,other.operation_key limit 1;
 if found then
  if peer.response is not null and peer.saved_at between now()-interval '5 minutes' and now() then
   -- Share only the validated non-contact estimate fields. Keep its original age.
   update icash_research_private.estimates set shared_hits=shared_hits+1 where operation_key=peer.operation_key;
   if p_policy->>'version'='financial-prefilter-v1' then
    update icash_research_private.estimates set query=p_query,exclusion_synced_at=generation,
     token=null,lease_until=null,retry_at=null,shared_from_operation=peer.operation_key,saved_at=peer.saved_at,updated_at=now(),
     response=jsonb_build_object('estimated_credits',jsonb_build_object('this_page',peer.response#>'{estimated_credits,this_page}',
      'breakdown',jsonb_build_object('people',peer.response#>'{estimated_credits,breakdown,people}')),
      'totals',jsonb_build_object('properties',peer.response#>'{totals,properties}'),
      'pagination',jsonb_build_object('total_results',peer.response#>'{pagination,total_results}'))
     where operation_key=op returning * into e;
    return jsonb_build_object('status','cached','response',e.response);
   end if;

   return jsonb_build_object('status','cached','response',jsonb_build_object('estimated_credits',
    jsonb_build_object('this_page',peer.response#>'{estimated_credits,this_page}',
     'breakdown',jsonb_build_object('people',peer.response#>'{estimated_credits,breakdown,people}'))));
  end if;
  return jsonb_build_object('status','held');
 end if;
 update icash_research_private.estimates set query=p_query,exclusion_synced_at=generation,token=t,
  lease_until=now()+interval '1 minute',retry_at=null,response=null,saved_at=null,updated_at=now() where operation_key=op;
 return jsonb_build_object('status','request','token',t);
end $function$
